#!/bin/sh
# Real-GPGME + real gpg binary replay for CVE-2026-129975. The attack input
# is an armored key generated by make-realkeys.sh; gpg's IMPORTED status line
# exceeds the 1024-byte buffer and the failing status callback takes the
# pinned early return before writeback. No network contact, no r5 claim.
set -u
cd "$(dirname "$0")"
here=$PWD
ev=$here/realgpg/evidence
mkdir -p "$ev"
pass=0; fail=0
check () {
  if [ "$1" = "$2" ]; then pass=$((pass+1));
  else fail=$((fail+1)); echo "FAIL: $3 (got '$1', want '$2')"; fi
}
count () { c=$(grep -c "$2" "$1" 2>/dev/null || true); echo "${c:-0}"; }
hash () { sha256sum "$1" | cut -d' ' -f1; }

check "$(hash ../pinned/engine-gpg.c)" \
  c4ef11bda841fc6d07c83063c6968a6db50db3393af2d661054c59b979311d55 \
  "pinned engine-gpg.c"
check "$(hash gpgme-2.2.0/src/engine-gpg.c)" \
  c4ef11bda841fc6d07c83063c6968a6db50db3393af2d661054c59b979311d55 \
  "built vulnerable source"
check "$(hash gpgme-fixed/src/engine-gpg.c)" \
  10179f7853d9284a21af4ad4ab94753654aa40119f9bdef43852e98482b75b08 \
  "built patched source"
check "$(grep -c 'gpg->status.buffer = buffer;' gpgme-2.3.1/src/engine-gpg.c)" \
  1 "2.3.1 immediate writeback"

for key in long-H long-Z long-7 short; do
  check "$([ -f "$here/realgpg/keys/$key.asc" ] && echo yes)" yes "key $key exists"
done

run_case () {
  name=$1; bin=$2; key=$3
  home=$here/realgpg/home-$name
  rm -rf "$home"
  mkdir -p "$home"
  chmod 700 "$home"
  ASAN_OPTIONS=detect_leaks=0 "./$bin" /usr/bin/gpg \
    "$here/realgpg/keys/$key.asc" "$home" >"$ev/$name.out" 2>&1
  echo $? >"$ev/$name.rc"
}

run_case realgpg-vuln-H status-trigger-realgpg long-H
run_case realgpg-vuln-Z status-trigger-realgpg long-Z
run_case realgpg-vuln-7 status-trigger-realgpg long-7
run_case realgpg-fixed-H status-trigger-realgpg-fixed long-H
run_case realgpg-231-H status-trigger-realgpg-231 long-H
run_case realgpg-vuln-short status-trigger-realgpg short
run_case realgpg-fixed-short status-trigger-realgpg-fixed short

for pair in H:0x48 Z:0x5a 7:0x37; do
  name=realgpg-vuln-${pair%%:*}
  byte=${pair##*:}
  check "$(cat "$ev/$name.rc")" 1 "$name rc"
  check "$(count "$ev/$name.out" 'attempting double-free')" 1 \
    "$name ASan double free"
  check "$(count "$ev/$name.out" 'gpg_release .*engine-gpg.c:602')" 1 \
    "$name second free in real gpg_release"
  check "$(count "$ev/$name.out" 'read_status .*engine-gpg.c:1494')" 1 \
    "$name first free in real read_status realloc"
  check "$(count "$ev/$name.out" "keyword=IMPORTED .*byte\[1000\]=$byte")" 1 \
    "$name chosen byte in real status callback"
done

for name in realgpg-fixed-H realgpg-231-H realgpg-vuln-short realgpg-fixed-short; do
  check "$(cat "$ev/$name.rc")" 0 "$name rc"
  check "$(count "$ev/$name.out" AddressSanitizer)" 0 "$name sanitizer-clean"
  check "$(count "$ev/$name.out" 'keyword=IMPORTED ')" 1 "$name callback reached"
done
check "$(count "$ev/realgpg-231-H.out" 'gpgme version=2.3.1')" 1 \
  "2.3.1 control is the real release"

echo "PASS=$pass FAIL=$fail"
[ "$fail" -eq 0 ]
